pub(crate) const UPDATE_MENU_ID: &str = "install-update";

/// "Update to X and Restart", kept so it can be put at the top of the
/// status item menu and taken off again. The menu is edited in place because
/// the NSMenu a right click pops up is the one taken off the item at launch.
pub(crate) struct UpdateMenu {
    pub(crate) menu: Menu<tauri::Wry>,
    pub(crate) item: MenuItem<tauri::Wry>,
    pub(crate) separator: PredefinedMenuItem<tauri::Wry>,
}

/// Clears AppKit's pressed look on the status item when its popover closes.
/// `keep_highlight_while_open` is what keeps it on until then.
#[cfg(target_os = "macos")]
pub(crate) fn hold_native_highlight(app: &AppHandle, id: &'static str, on: bool) {
    use objc2_foundation::MainThreadMarker;

    let handle = app.clone();
    let _ = app.run_on_main_thread(move || {
        let Some(tray) = handle.tray_by_id(id) else {
            return;
        };
        let _ = tray.with_inner_tray_icon(move |inner| {
            let Some(item) = inner.ns_status_item() else {
                return;
            };
            let Some(mtm) = MainThreadMarker::new() else {
                return;
            };
            if let Some(button) = item.button(mtm) {
                button.highlight(on);
            }
        });
    });
}

#[cfg(not(target_os = "macos"))]
pub(crate) fn hold_native_highlight(_app: &AppHandle, _id: &'static str, _on: bool) {}

/// Lays the status item out for what it actually carries.
///
/// `tray-icon` sets `NSImageLeft` whenever an image is set and never resets
/// it, so a glyph plus the empty title we always write reserves room for that
/// missing title and leaves a gap on the right of the icon. Reading the button
/// back rather than trusting the caller keeps this right when only one of the
/// pair changed.
#[cfg(target_os = "macos")]
pub(crate) fn align_status_item_content(tray: &tauri::tray::TrayIcon) {
    use objc2_app_kit::NSCellImagePosition;
    use objc2_foundation::MainThreadMarker;

    let _ = tray.with_inner_tray_icon(|inner| {
        let Some(item) = inner.ns_status_item() else {
            return;
        };
        let Some(mtm) = MainThreadMarker::new() else {
            return;
        };
        let Some(button) = item.button(mtm) else {
            return;
        };
        let position = match (
            button.image().is_some(),
            !button.title().to_string().is_empty(),
        ) {
            (true, true) => NSCellImagePosition::ImageLeft,
            (true, false) => NSCellImagePosition::ImageOnly,
            (false, _) => NSCellImagePosition::NoImage,
        };
        button.setImagePosition(position);
    });
}

/// Names the status item for VoiceOver, which otherwise reads only its
/// title, the short date, or nothing at all for a glyph-only style.
#[cfg(target_os = "macos")]
pub(crate) fn describe_status_item(tray: &tauri::tray::TrayIcon, text: &str) {
    use objc2::msg_send;
    use objc2_foundation::{MainThreadMarker, NSString};

    let text = text.to_string();
    let _ = tray.with_inner_tray_icon(move |inner| {
        let Some(item) = inner.ns_status_item() else {
            return;
        };
        let Some(mtm) = MainThreadMarker::new() else {
            return;
        };
        let Some(button) = item.button(mtm) else {
            return;
        };
        let label = (!text.is_empty()).then(|| NSString::from_str(&text));
        unsafe {
            let _: () = msg_send![&*button, setAccessibilityLabel: label.as_deref()];
        }
    });
}

/// What a status-item click should do. Split out so the left/right split can
/// be tested without standing up a menu bar extra.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum TrayClickIntent {
    Toggle,
    Menu,
    Ignore,
}

/// Both open on mouse-down, as a status item's menu does: the popover is up by
/// the time the button is released, with no beat in between.
pub(crate) fn tray_click_intent(button: MouseButton, state: MouseButtonState) -> TrayClickIntent {
    match (button, state) {
        (MouseButton::Left, MouseButtonState::Down) => TrayClickIntent::Toggle,
        (MouseButton::Right, MouseButtonState::Down) => TrayClickIntent::Menu,
        _ => TrayClickIntent::Ignore,
    }
}

/// The NSMenu stolen off the status item. AppKit objects are main-thread
/// only; this is only read from tray click handlers and setup, both of which
/// run there.
#[cfg(target_os = "macos")]
#[derive(Clone)]
pub(crate) struct TrayMenu(objc2::rc::Retained<objc2_app_kit::NSMenu>);

#[cfg(target_os = "macos")]
unsafe impl Send for TrayMenu {}
#[cfg(target_os = "macos")]
unsafe impl Sync for TrayMenu {}

#[cfg(target_os = "macos")]
pub(crate) type TrayMenuShare = Arc<Mutex<Option<TrayMenu>>>;

/// macOS 27 treats a resident `NSStatusItem` menu as the left-click action,
/// so the overlay never sees the click and the Settings/Quit menu opens
/// instead of the popover. Keep the menu off the item except while a
/// right-click presents it. See tauri-apps/tray-icon#355.
#[cfg(target_os = "macos")]
pub(crate) fn remember_status_item_menu(tray: &tauri::tray::TrayIcon, share: &TrayMenuShare) {
    use objc2_foundation::MainThreadMarker;
    let share = share.clone();
    let _ = tray.with_inner_tray_icon(move |inner| {
        inner.set_show_menu_on_right_click(false);
        let Some(item) = inner.ns_status_item() else {
            return;
        };
        let Some(mtm) = MainThreadMarker::new() else {
            return;
        };
        if let Ok(mut slot) = share.lock() {
            *slot = item.menu(mtm).map(TrayMenu);
        }
        item.setMenu(None);
    });
}

#[cfg(target_os = "macos")]
pub(crate) fn present_status_item_menu(tray: &tauri::tray::TrayIcon, menu: &TrayMenu) {
    // `NSMenu` is not Send, and `with_inner_tray_icon` requires a Send
    // closure, so the retained menu stays here and only a pointer crosses.
    let menu_ptr = objc2::rc::Retained::as_ptr(&menu.0) as usize;
    let _ = tray.with_inner_tray_icon(move |inner| {
        let Some(item) = inner.ns_status_item() else {
            return;
        };
        // SAFETY: `menu` is retained in TrayMenuShare for the process
        // lifetime, and this closure runs on the main thread.
        let menu = unsafe { &*(menu_ptr as *const objc2_app_kit::NSMenu) };
        #[allow(deprecated)]
        item.popUpStatusItemMenu(menu);
    });
}

pub(crate) fn handle_tray_click(
    tray: &tauri::tray::TrayIcon,
    event: TrayIconEvent,
    #[cfg(target_os = "macos")] menu: &TrayMenuShare,
) {
    let TrayIconEvent::Click {
        button,
        button_state,
        rect,
        ..
    } = event
    else {
        return;
    };
    match tray_click_intent(button, button_state) {
        TrayClickIntent::Toggle => toggle_calendar(
            tray.app_handle(),
            clicked_rect(tray.app_handle(), button_rect(tray, rect)),
        ),
        TrayClickIntent::Menu => {
            #[cfg(target_os = "macos")]
            {
                let menu = menu.lock().ok().and_then(|guard| guard.clone());
                if let Some(menu) = menu {
                    present_status_item_menu(tray, &menu);
                }
            }
        }
        TrayClickIntent::Ignore => {}
    }
}

pub(crate) fn handle_menu_action(app: &AppHandle, id: &str) {
    match id {
        "settings" => present_settings(app),
        "date-time" => {
            let _ = events::open_date_time_settings();
        }
        "quit" => app.exit(0),
        UPDATE_MENU_ID => install_update_from_menu(app),
        _ => {}
    }
}

pub(crate) fn build_tray_menu(app: &AppHandle) -> tauri::Result<Menu<tauri::Wry>> {
    // The shortcuts are shown as macOS menus show them, and work while the
    // menu is open.
    let settings = MenuItem::with_id(app, "settings", "Settings…", true, Some("CmdOrCtrl+,"))?;
    let date_time = MenuItem::with_id(
        app,
        "date-time",
        // muda strips a lone `&` as a mnemonic marker, leaving "Date  Time".
        "Date && Time Settings",
        true,
        None::<&str>,
    )?;
    let quit = MenuItem::with_id(app, "quit", "Quit Glance", true, Some("CmdOrCtrl+Q"))?;
    let separator = PredefinedMenuItem::separator(app)?;
    Menu::with_items(
        app,
        &[
            &settings as &dyn tauri::menu::IsMenuItem<tauri::Wry>,
            &date_time,
            &separator,
            &quit,
        ],
    )
}

pub(crate) fn build_tray(app: &AppHandle) -> tauri::Result<()> {
    let icon = tauri::image::Image::from_bytes(TRAY_ICON)?;
    let menu = build_tray_menu(app)?;
    app.manage(UpdateMenu {
        menu: menu.clone(),
        item: MenuItem::with_id(
            app,
            UPDATE_MENU_ID,
            "Update and Restart",
            true,
            None::<&str>,
        )?,
        separator: PredefinedMenuItem::separator(app)?,
    });
    #[cfg(target_os = "macos")]
    let status_menu: TrayMenuShare = Arc::new(Mutex::new(None));
    let calendar = TrayIconBuilder::with_id(TRAY_ID)
        .icon(icon)
        .icon_as_template(true)
        .tooltip("Glance")
        .menu(&menu)
        .show_menu_on_left_click(false)
        .on_menu_event(|app, event| handle_menu_action(app, event.id().as_ref()))
        .on_tray_icon_event({
            #[cfg(target_os = "macos")]
            let status_menu = status_menu.clone();
            move |tray, event| {
                handle_tray_click(
                    tray,
                    event,
                    #[cfg(target_os = "macos")]
                    &status_menu,
                );
            }
        })
        .build(app)?;
    #[cfg(target_os = "macos")]
    remember_status_item_menu(&calendar, &status_menu);
    Ok(())
}

/// Keeps the status item pressed for as long as the popover it opened is up,
/// as a status menu's item stays.
///
/// `tray-icon` lights the button on mouse-down and clears it first thing in
/// `mouseUp:`. Lighting it again afterwards left a frame without it, a blink
/// that the glass behind the popover picked up too. So the release that ends
/// an opening click never reaches `tray-icon`: the press look simply stays,
/// and closing the popover clears it.
#[cfg(target_os = "macos")]
pub(crate) fn keep_highlight_while_open(app: AppHandle) {
    use block2::RcBlock;
    use objc2_app_kit::{NSEvent, NSEventMask};
    use objc2_foundation::MainThreadMarker;
    use std::ptr::NonNull;

    let block = RcBlock::new(move |event: NonNull<NSEvent>| -> *mut NSEvent {
        let passthrough = event.as_ptr();
        let number = unsafe { event.as_ref() }.windowNumber();
        for (id, label) in [(TRAY_ID, CALENDAR_LABEL)] {
            let open = app
                .get_webview_window(label)
                .and_then(|window| window.is_visible().ok())
                .unwrap_or(false);
            if !open {
                continue;
            }
            let Some(tray) = app.tray_by_id(id) else {
                continue;
            };
            let on_item = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
            let found = on_item.clone();
            let _ = tray.with_inner_tray_icon(move |inner| {
                let Some(mtm) = MainThreadMarker::new() else {
                    return;
                };
                let window = inner
                    .ns_status_item()
                    .and_then(|item| item.button(mtm))
                    .and_then(|button| button.window());
                if window.is_some_and(|window| window.windowNumber() == number) {
                    found.store(true, Ordering::SeqCst);
                }
            });
            if on_item.load(Ordering::SeqCst) {
                return std::ptr::null_mut();
            }
        }
        passthrough
    });
    let monitor = unsafe {
        NSEvent::addLocalMonitorForEventsMatchingMask_handler(NSEventMask::LeftMouseUp, &block)
    };
    // The watch lasts as long as the app; nothing ever removes it.
    std::mem::forget(monitor);
}

#[cfg(not(target_os = "macos"))]
pub(crate) fn keep_highlight_while_open(_app: AppHandle) {}

/// Longest title the menu bar item takes. The month builds it from the date,
/// a countdown and a cut-short event name, well under this; the cap only
/// stops a webview gone wrong from filling the menu bar.
pub(crate) const TRAY_TITLE_MAX_CHARS: usize = 120;

/// Largest framed glyph accepted. The month draws an 18pt PNG of a few KB.
pub(crate) const TRAY_IMAGE_MAX_BYTES: usize = 64 * 1024;

/// Longest spoken description: the full date and a meeting's whole name.
pub(crate) const TRAY_DESCRIPTION_MAX_CHARS: usize = 300;

pub(crate) fn capped_line(text: Option<&str>, limit: usize) -> String {
    text.unwrap_or("")
        .chars()
        .filter(|character| !character.is_control())
        .take(limit)
        .collect()
}

pub(crate) fn tray_title_text(title: Option<&str>) -> String {
    capped_line(title, TRAY_TITLE_MAX_CHARS)
}

/// Status items keep their right edge, so a new title moves the left one,
/// and a reminder card on screen has to follow it. The item's frame is only
/// current once AppKit has laid the new title out, a moment after it is set.
pub(crate) fn follow_status_item(app: &AppHandle) {
    let handle = app.clone();
    std::thread::spawn(move || {
        std::thread::sleep(Duration::from_millis(120));
        let app = handle.clone();
        let _ = handle.run_on_main_thread(move || {
            let open = app
                .get_webview_window(REMINDER_LABEL)
                .and_then(|window| window.is_visible().ok())
                .unwrap_or(false);
            if !open {
                return;
            }
            if let Some(anchor) = tray_anchor(&app) {
                position_reminder(&app, anchor);
            }
        });
    });
}

/// Radius of the update dot and the clear ring around it, as shares of the
/// glyph's height. On the 18pt status item that is a 5pt dot with a 1.25pt
/// gap: news, the size other menu bar apps use, not an alarm.
pub(crate) const UPDATE_DOT_RADIUS: f32 = 5.0 / 36.0;

pub(crate) const UPDATE_DOT_GAP: f32 = 2.5 / 36.0;

/// Puts the update dot in the top-right corner of a template glyph, cut out
/// of whatever it lands on so it reads against a filled badge as well as
/// against bare strokes. Only alpha matters to a template image; macOS draws
/// the dot in the menu bar's own ink.
pub(crate) fn with_update_dot(rgba: &[u8], width: u32, height: u32) -> Vec<u8> {
    let radius = height as f32 * UPDATE_DOT_RADIUS;
    let clear = radius + height as f32 * UPDATE_DOT_GAP;
    let (cx, cy) = (width as f32 - radius, radius);
    let mut out = rgba.to_vec();
    for y in 0..height {
        for x in 0..width {
            let distance = (x as f32 + 0.5 - cx).hypot(y as f32 + 0.5 - cy);
            let keep = (distance - clear + 0.5).clamp(0.0, 1.0);
            let dot = (radius + 0.5 - distance).clamp(0.0, 1.0);
            let pixel = &mut out[((y * width + x) * 4) as usize..][..4];
            let alpha = (f32::from(pixel[3]) * keep).max(dot * 255.0);
            if dot > 0.0 {
                pixel[..3].fill(0);
            }
            pixel[3] = alpha.round() as u8;
        }
    }
    out
}

/// Writes the calendar status item's glyph, dotted while an update waits.
/// A text-only style has no glyph to mark, so the dot stands by itself
/// ahead of the text.
pub(crate) fn paint_tray_glyph(tray: &tauri::tray::TrayIcon, base: Option<&[u8]>) {
    let base = base.and_then(|data| tauri::image::Image::from_bytes(data).ok());
    let glyph = match (base, updates::available().is_some()) {
        (Some(image), false) => Some(image),
        (Some(image), true) => {
            let (width, height) = (image.width(), image.height());
            Some(tauri::image::Image::new_owned(
                with_update_dot(image.rgba(), width, height),
                width,
                height,
            ))
        }
        (None, true) => {
            let height = 36;
            let width = (height as f32 * UPDATE_DOT_RADIUS * 2.0).ceil() as u32 + 2;
            let blank = vec![0; (width * height * 4) as usize];
            Some(tauri::image::Image::new_owned(
                with_update_dot(&blank, width, height),
                width,
                height,
            ))
        }
        (None, false) => None,
    };
    let showing = glyph.is_some();
    let _ = tray.set_icon(glyph);
    if showing {
        let _ = tray.set_icon_as_template(true);
    }
    #[cfg(target_os = "macos")]
    align_status_item_content(tray);
    #[cfg(target_os = "macos")]
    fit_status_item_to_menu_bar(tray);
}

/// The glyph's height in the menu bar. The PNGs are drawn at 18pt with
/// their ink filling most of it, which stood taller than the system's own
/// items; at 15pt the ink matches Control Centre and Spotlight.
#[cfg(target_os = "macos")]
const GLYPH_HEIGHT: f64 = 15.0;

/// The cutout badge carries the date as text inside it, so it keeps the
/// height that lets that text read at the size of the title beside it.
#[cfg(target_os = "macos")]
const BADGE_HEIGHT: f64 = 18.0;

/// The title's size: what macOS gives the battery percentage, a step under
/// the clock, so the item reads as a status beside the clock rather than a
/// second one.
#[cfg(target_os = "macos")]
const TITLE_SIZE_DROP: f64 = 2.0;

/// How far the title is raised so its baseline meets the clock's and the
/// other status items': a plain title sits half a point low beside a glyph.
#[cfg(target_os = "macos")]
const TITLE_BASELINE_RAISE: f64 = 0.5;

/// Sizes the glyph like the system's own items and sets the title in the
/// system font at the battery percentage's size, regular weight, with digits
/// of one width so a countdown does not shift sideways as it ticks.
#[cfg(target_os = "macos")]
pub(crate) fn fit_status_item_to_menu_bar(tray: &tauri::tray::TrayIcon) {
    use objc2::runtime::AnyObject;
    use objc2::AnyThread;
    use objc2_app_kit::{
        NSBaselineOffsetAttributeName, NSFont, NSFontAttributeName, NSFontWeightRegular,
    };
    use objc2_foundation::{MainThreadMarker, NSAttributedString, NSDictionary, NSNumber, NSSize};

    let _ = tray.with_inner_tray_icon(|inner| {
        let Some(item) = inner.ns_status_item() else {
            return;
        };
        let Some(mtm) = MainThreadMarker::new() else {
            return;
        };
        let Some(button) = item.button(mtm) else {
            return;
        };
        if let Some(image) = button.image() {
            let current = image.size();
            // Square glyphs are icons; a wide one is the cutout badge.
            let height = if current.width > current.height * 1.25 {
                BADGE_HEIGHT
            } else {
                GLYPH_HEIGHT
            };
            if current.height > 0.0 && (current.height - height).abs() > 0.01 {
                let width = current.width * height / current.height;
                image.setSize(NSSize::new(width, height));
                button.setImage(Some(&image));
            }
        }
        let title = button.title();
        if title.length() == 0 {
            return;
        }
        let size = NSFont::menuBarFontOfSize(0.0).pointSize() - TITLE_SIZE_DROP;
        let font =
            unsafe { NSFont::monospacedDigitSystemFontOfSize_weight(size, NSFontWeightRegular) };
        let raise = NSNumber::new_f64(TITLE_BASELINE_RAISE);
        let font_object: &AnyObject = &font;
        let raise_object: &AnyObject = &raise;
        let primary = unsafe {
            NSDictionary::from_slices(
                &[NSFontAttributeName, NSBaselineOffsetAttributeName],
                &[font_object, raise_object],
            )
        };
        let styled = unsafe {
            NSAttributedString::initWithString_attributes(
                NSAttributedString::alloc(),
                &title,
                Some(&primary),
            )
        };
        button.setAttributedTitle(&styled);
    });
}

/// Follows a check's verdict into the menu bar: the dot on the glyph, and the
/// install item at the top of the menu. `None` takes both away.
pub(crate) fn show_update_available(app: &AppHandle, version: Option<&str>) {
    if let Some(update) = app.try_state::<UpdateMenu>() {
        let shown = update.menu.get(UPDATE_MENU_ID).is_some();
        match version {
            Some(version) => {
                let _ = update
                    .item
                    .set_text(format!("Update to {version} and Restart"));
                if !shown {
                    let _ = update
                        .menu
                        .prepend_items(&[&update.item, &update.separator]);
                }
            }
            None if shown => {
                let _ = update.menu.remove(&update.item);
                let _ = update.menu.remove(&update.separator);
            }
            None => {}
        }
    }
    let app = app.clone();
    let _ = app.clone().run_on_main_thread(move || {
        let Some(tray) = app.tray_by_id(TRAY_ID) else {
            return;
        };
        let base = app
            .state::<AppState>()
            .tray_glyph
            .lock()
            .ok()
            .and_then(|glyph| glyph.clone());
        paint_tray_glyph(&tray, base.as_deref());
    });
}

/// "Update and Restart" from the menu. Progress shows on the Settings pill if
/// the window is open; a failure brings it forward so the reason can be read.
pub(crate) fn install_update_from_menu(app: &AppHandle) {
    let app = app.clone();
    tauri::async_runtime::spawn(async move {
        if let Err(message) = updates::install(&app).await {
            let _ = app.emit("update-failed", message);
            // This runs on a worker thread; windows are AppKit's, main only.
            let shown = app.clone();
            let _ = app.run_on_main_thread(move || present_settings(&shown));
        }
    });
}
